Object.assign(SNIP,{"l27vung": "int dem = 0;                 // vùng toàn cục: sống suốt chương trình\n\nvoid f(int n) {\n    int x = n * 2;           // stack: sinh ra khi f được gọi, mất khi f trả về\n    static int lan = 0;      // vùng tĩnh: khởi tạo một lần, giữ giá trị giữa các lần gọi\n    int* p = new int(x);     // p nằm trên stack, ô *p nằm trên heap\n    delete p;                // heap: chỉ được trả lại khi gọi delete\n}", "l27heap": "int n;\ncin >> n;\nint* a = new int[n];         // xin n ô int liền nhau trên heap\nfor (int i = 0; i < n; i++) a[i] = i * i;\ndelete[] a;                  // trả lại; new[] đi với delete[]"});PRESET_NOTES["l27"]={"Ví dụ: Khung stack của các lời gọi hàm": "Khi binhPhuong đang chạy có ba khung chồng lên nhau: main, tongBinhPhuong, binhPhuong. Mỗi khung có biến riêng (kq, s…). binhPhuong trả về là khung của nó biến mất; lần gọi binhPhuong(b) sau đó dựng một khung mới ở đúng chỗ cũ.", "Ví dụ: Đệ quy và địa chỉ giảm dần": "Mỗi lời gọi dem có ô x riêng, ở địa chỉ thấp hơn lời gọi trước: stack lớn dần về phía địa chỉ nhỏ. Bốn khung cùng tồn tại khi dem(0) đang chạy, rồi lần lượt được gỡ theo thứ tự ngược lại.", "Ví dụ: Dữ liệu trên heap sống lâu hơn hàm": "Con trỏ a là biến cục bộ của taoMang, mất khi hàm trả về. Nhưng khối 4 ô nó trỏ tới nằm trên heap nên vẫn còn: main nhận lại địa chỉ đó trong p và dùng tiếp. Cuối cùng main có trách nhiệm delete[] khối này.", "Ví dụ: Mảng có kích thước nhập lúc chạy": "Kích thước n chỉ biết khi chạy, nên khối n ô được xin trên heap. Sau delete[] a, khối được đánh dấu đã trả lại; con trỏ a vẫn còn giữ địa chỉ cũ nhưng không được dùng nữa.", "Ví dụ: Biến toàn cục và biến static": "tam là biến cục bộ: mỗi lần gọi được tạo lại bằng 0. ma là static: chỉ khởi tạo bằng 100 một lần, sau đó giữ giá trị giữa các lần gọi (101, 102, 103). tongGoi là biến toàn cục, hàm nào cũng đọc và sửa được. Hai biến này nằm ở vùng tĩnh, không nằm trong khung của hàm.", "Lỗi: mảng cục bộ quá lớn làm tràn stack": "3 000 000 số int là 12 MB, vượt vùng stack 8 MB của Linux: chương trình dừng với Segmentation fault ngay khi vào main. Sửa: vector<int> a(3000000); hoặc int* a = new int[3000000]; hoặc đưa mảng ra ngoài main thành biến toàn cục."};EX_HINTS["l27"]=[["a = new int[n]; cho n ô liền nhau; dùng a[i] như mảng thường.", "Xong việc thì delete[] a; (có cặp ngoặc vuông vì đã xin bằng new[])."], ["Mảng cục bộ long long a[1000] sẽ bị hủy khi hàm trả về; phải dùng new long long[n].", "Phần tử thứ i là a0 + i * d."], ["static int dem = 0; chỉ chạy phần khởi tạo ở lần gọi đầu tiên; các lần sau dem giữ giá trị cũ.", "Không dùng biến i của main: bài muốn hàm tự nhớ."]];
/* ===================== BÀI 27 · Stack và heap ===================== */
/* Bài 27 · Stack và heap
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P27=[{label:"Ví dụ: Khung stack của các lời gọi hàm",input:"",code:"#include <iostream>\nusing namespace std;\n\nint binhPhuong(int x) {\n    int kq = x * x;\n    return kq;\n}\n\nint tongBinhPhuong(int a, int b) {\n    int s = binhPhuong(a) + binhPhuong(b);\n    return s;\n}\n\nint main() {\n    int u = 3, v = 4;\n    int t = tongBinhPhuong(u, v);\n    cout << t << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Đệ quy và địa chỉ giảm dần",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid dem(int n) {\n    int x = n;\n    cout << \"n = \" << n << \", &x = \" << &x << \"\\n\";\n    if (n > 0) dem(n - 1);\n}\n\nint main() {\n    dem(3);\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Dữ liệu trên heap sống lâu hơn hàm",input:"",code:"#include <iostream>\nusing namespace std;\n\nint* taoMang(int n) {\n    int* a = new int[n];\n    for (int i = 0; i < n; i++) {\n        a[i] = (i + 1) * 10;\n    }\n    return a;\n}\n\nint main() {\n    int* p = taoMang(4);\n    cout << p[0] << \" \" << p[3] << \"\\n\";\n    delete[] p;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Mảng có kích thước nhập lúc chạy",input:"5\n4 8 15 16 23",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int* a = new int[n];\n    for (int i = 0; i < n; i++) {\n        cin >> a[i];\n    }\n    long long tong = 0;\n    for (int i = 0; i < n; i++) tong += a[i];\n    cout << \"Tong = \" << tong << \"\\n\";\n    delete[] a;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Biến toàn cục và biến static",input:"",code:"#include <iostream>\nusing namespace std;\n\nint tongGoi = 0;\n\nint layMa() {\n    static int ma = 100;\n    int tam = 0;\n    ma++;\n    tam++;\n    tongGoi++;\n    return ma + tam;\n}\n\nint main() {\n    cout << layMa() << \"\\n\";\n    cout << layMa() << \"\\n\";\n    cout << layMa() << \"\\n\";\n    cout << \"Da goi \" << tongGoi << \" lan\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: mảng cục bộ quá lớn làm tràn stack",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[3000000];\n    a[0] = 1;\n    cout << a[0] << \"\\n\";\n    return 0;\n}"}];
const sim27=makeSim2(document.getElementById("sim-l27"),{id:"s27",presets:P27});
makeEx2(document.getElementById("ex-l27"),sim27,[{t:"In ngược bằng mảng động",d:"Nhập n (1 ≤ n ≤ 10<sup>5<\/sup>) rồi n số nguyên. Xin mảng <code>new int[n]<\/code> để lưu, in các số theo thứ tự ngược lại, rồi <code>delete[]<\/code>.",tests:[{in:"5\n1 2 3 4 5",out:"5 4 3 2 1"},{in:"1\n42",out:"42"},{in:"3\n-1 0 1",out:"1 0 -1"},{in:"4\n7 7 8 8",out:"8 8 7 7"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int* a = nullptr;   // xin n ô trên heap\n    // đọc n số vào a, in ngược, rồi trả lại vùng nhớ\n    return 0;\n}",need:/new\s+int\s*\[[\s\S]*delete\s*\[\s*\]/,needMsg:"Hãy dùng new int[n] để xin mảng và delete[] để trả lại."},{t:"Cấp số cộng trên heap",d:"Nhập n, a0, d (1 ≤ n ≤ 1000, |a0|, |d| ≤ 10<sup>6<\/sup>). Viết hàm <code>long long* capSoCong(int n, long long a0, long long d)<\/code> xin một mảng n phần tử trên heap, điền a0, a0 + d, a0 + 2d, … rồi trả về con trỏ. main in mảng và <code>delete[]<\/code>.",tests:[{in:"5 2 3",out:"2 5 8 11 14"},{in:"1 7 100",out:"7"},{in:"4 10 -4",out:"10 6 2 -2"},{in:"3 1000000 1000000",out:"1000000 2000000 3000000"}],start:"#include <iostream>\nusing namespace std;\n\nlong long* capSoCong(int n, long long a0, long long d) {\n    // xin mảng trên heap (không dùng mảng cục bộ: nó mất khi hàm trả về)\n    return nullptr;\n}\n\nint main() {\n    int n;\n    long long a0, d;\n    cin >> n >> a0 >> d;\n    long long* a = capSoCong(n, a0, d);\n    for (int i = 0; i < n; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    delete[] a;\n    return 0;\n}",need:/long\s+long\s*\*\s*capSoCong\s*\([\s\S]*new\s+long\s+long\s*\[/,needMsg:"Hãy giữ hàm long long* capSoCong(...) và xin mảng bằng new long long[n]."},{t:"Đánh số thứ tự bằng biến static",d:"Nhập n (1 ≤ n ≤ 1000) rồi n từ (mỗi từ không có dấu cách). Viết hàm <code>int soTiepTheo()<\/code> dùng biến <code>static<\/code> bên trong để trả về 1, 2, 3, … ở các lần gọi liên tiếp. In mỗi từ trên một dòng dạng <code>so. tu<\/code>.",tests:[{in:"3\nmot hai ba",out:"1. mot\n2. hai\n3. ba"},{in:"1\nxin",out:"1. xin"},{in:"4\na b c d",out:"1. a\n2. b\n3. c\n4. d"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint soTiepTheo() {\n    // một biến static giữ số đã phát ra lần trước\n    return 0;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int i = 0; i < n; i++) {\n        string tu;\n        cin >> tu;\n        cout << soTiepTheo() << \". \" << tu << \"\\n\";\n    }\n    return 0;\n}",need:/int\s+soTiepTheo\s*\(\s*\)\s*\{[^}]*\bstatic\s+int\b/,needMsg:"Hãy dùng một biến static bên trong hàm int soTiepTheo()."}]);

